def _cle(texte):
    """Clé de comparaison (accents, casse, ponctuation ignorés) — copie volontaire d'une logique
    simple : une migration reste un instantané indépendant du code applicatif."""
    sans_accents = ''.join(c for c in unicodedata.normalize('NFKD', texte or '') if not unicodedata.combining(c))
    return ' '.join(re.findall(r"[a-z0-9+#]+", sans_accents.lower()))


def rattacher_competences_existantes(apps, schema_editor):
    """Rattache les compétences d'offres ET de candidats déjà saisies à une entrée du référentiel
    (libellé ou synonyme exact), pour que le matching les compare par identifiant. Jamais de
    rapprochement approximatif ; les compétences hors référentiel restent sans lien."""
    Referentiel = apps.get_model('jobs', 'CompetenceReferentiel')
    refs = list(Referentiel.objects.all().order_by('id'))
    index = {}
    for ref in refs:
        index.setdefault(_cle(ref.label), ref.id)
    for ref in refs:
        for synonyme in re.split(r"[,;|]", ref.synonymes or ''):
            if _cle(synonyme):
                index.setdefault(_cle(synonyme), ref.id)
    for nom_modele in ('CompetenceOffre', 'CompetenceCandidat'):
        Modele = apps.get_model('jobs', nom_modele)
        for ligne in Modele.objects.filter(competence_ref__isnull=True):
            ref_id = index.get(_cle(ligne.label))
            if ref_id:
                Modele.objects.filter(pk=ligne.pk).update(competence_ref_id=ref_id)


